// 热冷签署共用原成员、成年和专项Grant，代任、今天Owner与旧Family换控都不成为新轮公权。
#pragma once
#include "political_successor_round_rules.hpp"
#include "resident/domains/politics/political_member_history.hpp"
#include "resident/domains/politics/politics_internal.hpp"
#include "resident/domains/family/actor_presence_read.hpp"
namespace hanmo::resident::successor_round_detail {
// 原意愿一旦拒绝/撤回永久关闭，实际就任后也不能反向撤回公职。
inline const PoliticalSuccessorRoundAnswer* accepted(const PoliticalSuccessorRoundState& s,const StableId& id){for(const auto& row:s.answers.rows())if(row.second.nomination_fact_id==id&&row.second.accepted)return &row.second;return nullptr;}
inline bool closed(const PoliticalSuccessorRoundState& s,const StableId& id){for(const auto& row:s.answers.rows())if(row.second.nomination_fact_id==id&&!row.second.accepted)return true;for(const auto& row:s.withdrawals.rows())if(row.second.nomination_fact_id==id)return true;return false;}
inline bool acceded(const PoliticalSuccessorRoundState& s,const StableId& id){for(const auto& row:s.accessions.rows()){const auto* a=s.answers.find(row.second.acceptance_fact_id);if(a&&a->nomination_fact_id==id)return true;}return false;}
// 实际同首府到场与原空闲门共用，军事/行旅坐标不能冒柜台本人。
inline Status contact(const PoliticalSuccessorRoundContext& x,const PoliticalSuccessionPolicy& p,const StableId& actor){auto v=politics_detail::available(x.common,x.activity,actor);if(!v.ok)return v;const auto place=politics_detail::place(x.common,actor);return place&&place->place_id==p.seat_place_id?common_success():common_failure("PoliticalSuccessorRoundSeatRequired",actor);}
inline Status member_now(const PoliticalSuccessorRoundContext& x,const PoliticalSuccessionPolicy& p,const StableId& actor){OrganizationAccess access(x.common,x.organizations,x.organization_catalog,x.economy);return access.actor_accepts_duty(actor,p.organization_id)?common_success():common_failure("PoliticalSuccessorRoundMemberUnavailable",actor);}
// 历史在世按真正死因截面，实际当面由永久本人业务记录见证。
inline Status person_before(const PoliticalSuccessorRoundContext& x,const StableId& actor,Integer tick,const StableId& fact){auto source=read_actor_presence_before_fact(x.common,x.common_catalog,x.death_origin,actor,tick,fact);if(!source.ok)return {false,{},source.error};const auto* person=x.common.state().actors.find(actor);constexpr Integer bound=2147483647;if(!source.value.alive)return common_failure("PoliticalSuccessorRoundSignerDead",actor);if(!person||!person->birth_tick||*person->birth_tick< -bound||tick<0||tick>bound||*person->birth_tick>tick)return common_failure("ActorAgeUnknown",actor);return tick-*person->birth_tick>=18*720?common_success():common_failure("OfficeRequiresAdult",actor);}
inline Status member_before(const PoliticalSuccessorRoundContext& x,const PoliticalSuccessionPolicy& p,const StableId& actor,Integer tick,const StableId& fact){return validate_political_historical_member_duty(x.common,x.organizations,x.organization_catalog,{p.organization_id,p.leader_office_id,0,actor},tick,fact,PoliticalMemberHistoryUse::political_successor_round);}
// 一份新专项Grant在签发和接受各自当时完整有效，不能拼合不同来源或延长旧授权。
inline Status grant(const PoliticalSuccessorRoundContext& x,const PoliticalSuccessorRoundPolicy& p,const PoliticalSuccessionPolicy& original,const StableId& saved,const StableId& command,Integer tick){const auto* g=x.organization_catalog.grants.find(saved);const auto* office=x.organization_catalog.offices.find(original.leader_office_id);if(!g||!office||saved!=p.nomination_grant_id||g->office_id!=office->id||std::find(office->grant_ids.begin(),office->grant_ids.end(),saved)==office->grant_ids.end()||tick<g->valid_from||(g->valid_until&&tick>*g->valid_until)||std::find(g->allowed_command_kinds.begin(),g->allowed_command_kinds.end(),command)==g->allowed_command_kinds.end()||std::none_of(g->scopes.begin(),g->scopes.end(),[&](const ScopeRef& scope){return scope.kind==ScopeRef::Kind::site&&scope.id==original.seat_place_id;}))return common_failure("PoliticalSuccessorRoundSpecificGrantRequired",saved);return common_success();}
// 签署绑定同一真实任期，原首任继续走1版，普通更职不获得这一后继制度许可。
inline Status head(const PoliticalSuccessorRoundContext& x,const PoliticalSuccessorRoundPolicy& p,const StableId& actor,Integer epoch,const StableId& expected_source,const StableId& expected_change,Integer tick,const StableId& boundary){auto read=boundary.empty()?read_political_successor_round_head(x.heads,x.catalog,x.state,p.id):read_political_successor_round_head_before(x.heads,x.catalog,x.state,p.id,tick,boundary);if(!read.ok)return {false,{},read.error};if(!read.value||read.value->origin==PoliticalHeadOrigin::authored||read.value->actor_id!=actor||read.value->office_epoch!=epoch||read.value->source_fact_id!=expected_source||(!expected_change.empty()&&read.value->office_change_fact_id!=expected_change))return common_failure("PoliticalSuccessorRoundHeadChanged",p.id);return common_success();}
}
